/// <summary>
/// Customer free-text invoice posted business event.
/// </summary>
[BusinessEvents(classStr(METClaimCustFreeTextInvoicePostedBusinessEventContract), 'Claim Free Text Invoice Posting Business Event', 'This business event is triggered when the claim free text invoice is posted', ModuleAxapta::Customer)]
public final class METClaimCustFreeTextInvoicePostedBusinessEvent extends BusinessEventsBase
{
    private SourceDocumentHeaderRecId sourceDocumentHeaderRecId;

}

Method.Source:
/// <summary>
/// Parm method for SourceDocumentHeaderRecId
/// </summary>
/// <param name = "_sourceDocumentHeaderRecId">SourceDocumentHeaderRecId</param>
/// <returns>SourceDocumentHeaderRecId</returns>
private SourceDocumentHeaderRecId parmSourceDocumentHeaderRecId(SourceDocumentHeaderRecId _sourceDocumentHeaderRecId = sourceDocumentHeaderRecId)
{
    sourceDocumentHeaderRecId = _sourceDocumentHeaderRecId;

    return sourceDocumentHeaderRecId;
}

/// <summary>
/// Creates a <c>METClaimCustFreeTextInvoicePostedBusinessEvent</c> from a SourceDocumentHeaderRecId.
/// </summary>
/// <param name = "_sourceDocumentHeaderRecId"> The A record identifier for the <c>SourceDocumentHeader</c> associated with the invoice.</param>
/// <returns>A <c>METClaimCustFreeTextInvoicePostedBusinessEvent</c>.</returns>
public static METClaimCustFreeTextInvoicePostedBusinessEvent newFromSourceDocumentHeaderRecId(SourceDocumentHeaderRecId _sourceDocumentHeaderRecId)
{
    METClaimCustFreeTextInvoicePostedBusinessEvent businessEvent = new METClaimCustFreeTextInvoicePostedBusinessEvent();
    businessEvent.parmSourceDocumentHeaderRecId(_sourceDocumentHeaderRecId);
    InvoicePostedBusinessEvent::newFromInvoiceJour(InvoicePostedBusinessEventEntityType::CustFreeTextInvoiceEntity, CustInvoiceJour::findFromSourceDocumentHeader(_sourceDocumentHeaderRecId)).send();
    return businessEvent;
}

/// <summary>
/// Build contract method
/// </summary>
/// <returns>BusinessEventsContract</returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return METClaimCustFreeTextInvoicePostedBusinessEventContract::newFromCustInvoiceJour(CustInvoiceJour::findFromSourceDocumentHeader(sourceDocumentHeaderRecId));
}
